begin;

-- Expand the earlier MVP constraints. Legacy Alpha/Beta rows remain permitted only so this migration can upgrade an already-seeded development database.
alter table public.card_sets drop constraint if exists card_sets_id_check;
alter table public.card_sets add constraint card_sets_id_check check (id in ('alpha','beta','ancient','oath','legionnaire'));
update public.card_sets set active=false where id in ('alpha','beta');
alter table public.cards drop constraint if exists cards_rarity_check;
alter table public.cards add constraint cards_rarity_check check (rarity in ('common','uncommon','rare','epic','legendary'));

update public.game_versions set status='retired' where status='active' and version<>'three-packs-1.0.0';





