insert into public.abilities(id,game_version_id,banner_id,name,timing,mechanics,stacking_rule,definition,active) select 'brace',id,'bastion_orders','Brace','round_start','If this unit is in position 1 or 2, it gains 2 brace points. Each point prevents 1 Steel or Shot damage after armor and is then spent. Unspent points expire when the unit takes its turn.','Multiple grants do not stack; use the highest point value.','{"values":{"bracePoints":2,"eligiblePositions":[1,2]},"interactions":["Does not prevent Spell or direct damage.","Damage reduced to 0 does not trigger on-damage effects.","A stunned unit still loses unspent points at its skipped turn."]}'::jsonb,true from public.game_versions where version='three-packs-1.0.0' on conflict(id) do update set game_version_id=excluded.game_version_id,banner_id=excluded.banner_id,name=excluded.name,timing=excluded.timing,mechanics=excluded.mechanics,stacking_rule=excluded.stacking_rule,definition=excluded.definition,active=true;
insert into public.abilities(id,game_version_id,banner_id,name,timing,mechanics,stacking_rule,definition,active) select 'shieldwall',id,'bastion_orders','Shieldwall','damage_mitigation','While this unit has at least 1 armor, adjacent allies take 1 less Steel and Shot damage after their own armor. A unit can receive protection from both neighbors.','Additive from left and right neighbors, capped at 2.','{"values":{"reductionPerNeighbor":1,"maximumReduction":2},"interactions":["Broken Formation disables adjacency benefits.","Does not protect the bearer.","Reduction applies after armor absorption but before brace points."]}'::jsonb,true from public.game_versions where version='three-packs-1.0.0' on conflict(id) do update set game_version_id=excluded.game_version_id,banner_id=excluded.banner_id,name=excluded.name,timing=excluded.timing,mechanics=excluded.mechanics,stacking_rule=excluded.stacking_rule,definition=excluded.definition,active=true;
insert into public.abilities(id,game_version_id,banner_id,name,timing,mechanics,stacking_rule,definition,active) select 'forgeheart',id,'bastion_orders','Forgeheart','after_damage','The first time this unit falls from positive armor to 0 armor, restore 2 armor after the current action finishes.','Additional copies add no uses.','{"values":{"restoredArmor":2,"usesPerBattle":1},"interactions":["A lethal hit still defeats the unit before armor is restored.","An armor purge that deals no damage can trigger it.","The restored armor cannot exceed printed maximum armor."]}'::jsonb,true from public.game_versions where version='three-packs-1.0.0' on conflict(id) do update set game_version_id=excluded.game_version_id,banner_id=excluded.banner_id,name=excluded.name,timing=excluded.timing,mechanics=excluded.mechanics,stacking_rule=excluded.stacking_rule,definition=excluded.definition,active=true;
insert into public.abilities(id,game_version_id,banner_id,name,timing,mechanics,stacking_rule,definition,active) select 'bannerhold',id,'bastion_orders','Bannerhold','continuous','While this unit occupies position 1 or 2, positive numeric effects created by allied summoners are increased by 1 for this unit only.','Does not stack with another Bannerhold.','{"values":{"bonus":1,"eligiblePositions":[1,2]},"interactions":["Does not increase ability-grant effects.","Recalculates immediately after position changes.","A +0 or conditional effect remains unchanged."]}'::jsonb,true from public.game_versions where version='three-packs-1.0.0' on conflict(id) do update set game_version_id=excluded.game_version_id,banner_id=excluded.banner_id,name=excluded.name,timing=excluded.timing,mechanics=excluded.mechanics,stacking_rule=excluded.stacking_rule,definition=excluded.definition,active=true;
insert into public.abilities(id,game_version_id,banner_id,name,timing,mechanics,stacking_rule,definition,active) select 'retinue',id,'bastion_orders','Retinue','round_start','If this unit has a living ally immediately ahead and immediately behind it, all three gain 1 temporary armor until round end.','Each Retinue bearer may create a separate layer; maximum 2 temporary armor per unit.','{"values":{"temporaryArmor":1,"requiredNeighbors":2},"interactions":["Temporary armor is lost at round end before damage-over-time resolves.","Broken Formation suppresses this ability.","Summoned units can satisfy the neighbor check next round."]}'::jsonb,true from public.game_versions where version='three-packs-1.0.0' on conflict(id) do update set game_version_id=excluded.game_version_id,banner_id=excluded.banner_id,name=excluded.name,timing=excluded.timing,mechanics=excluded.mechanics,stacking_rule=excluded.stacking_rule,definition=excluded.definition,active=true;
insert into public.abilities(id,game_version_id,banner_id,name,timing,mechanics,stacking_rule,definition,active) select 'oathkeeper',id,'bastion_orders','Oathkeeper','before_lethal_damage','Once per battle, when an adjacent ally would be defeated by direct attack damage, this unit takes that post-mitigation damage instead. The ally takes 0.','Each bearer has its own use; the nearest frontward eligible bearer resolves first.','{"values":{"usesPerBattle":1},"interactions":["Cannot intercept fatigue, Doom Count, or other indirect damage.","If the bearer is defeated, excess damage does not return to the ally.","Does not trigger if displacement has broken adjacency."]}'::jsonb,true from public.game_versions where version='three-packs-1.0.0' on conflict(id) do update set game_version_id=excluded.game_version_id,banner_id=excluded.banner_id,name=excluded.name,timing=excluded.timing,mechanics=excluded.mechanics,stacking_rule=excluded.stacking_rule,definition=excluded.definition,active=true;
insert into public.abilities(id,game_version_id,banner_id,name,timing,mechanics,stacking_rule,definition,active) select 'bloodscent',id,'wild_courts','Bloodscent','damage_calculation','Deal +1 attack damage to a target that began the action below its maximum health.','Multiple copies do not stack.','{"values":{"bonusDamage":1},"interactions":["Checked before the attack roll, not after reflected or linked damage.","Applies to Steel, Shot, and Spell attacks.","Temporary maximum-health loss can make a target wounded."]}'::jsonb,true from public.game_versions where version='three-packs-1.0.0' on conflict(id) do update set game_version_id=excluded.game_version_id,banner_id=excluded.banner_id,name=excluded.name,timing=excluded.timing,mechanics=excluded.mechanics,stacking_rule=excluded.stacking_rule,definition=excluded.definition,active=true;
insert into public.abilities(id,game_version_id,banner_id,name,timing,mechanics,stacking_rule,definition,active) select 'packmark',id,'wild_courts','Packmark','after_hit','The first Wild Courts attack that hits each round marks its target until round end. Later Wild Courts attacks against that target gain +1 damage.','One team mark per target; it cannot stack.','{"values":{"bonusDamage":1,"marksPerTeamPerRound":1},"interactions":["Misses do not place the mark.","The marking attack does not receive the bonus.","A copied or stolen Packmark still keys from the attacker’s current Banner."]}'::jsonb,true from public.game_versions where version='three-packs-1.0.0' on conflict(id) do update set game_version_id=excluded.game_version_id,banner_id=excluded.banner_id,name=excluded.name,timing=excluded.timing,mechanics=excluded.mechanics,stacking_rule=excluded.stacking_rule,definition=excluded.definition,active=true;
insert into public.abilities(id,game_version_id,banner_id,name,timing,mechanics,stacking_rule,definition,active) select 'pounce',id,'wild_courts','Pounce','battle_start','If this unit starts in position 4, 5, or 6, it makes a 1-damage Steel strike against the enemy rearmost unit before round 1. This strike cannot critically hit.','Every bearer triggers in normal speed order.','{"values":{"openingDamage":1,"eligiblePositions":[4,5,6]},"interactions":["Uses normal accuracy and can be intercepted.","Does not count as the unit’s round action.","Battle-start defeats are removed before round 1 initiative is built."]}'::jsonb,true from public.game_versions where version='three-packs-1.0.0' on conflict(id) do update set game_version_id=excluded.game_version_id,banner_id=excluded.banner_id,name=excluded.name,timing=excluded.timing,mechanics=excluded.mechanics,stacking_rule=excluded.stacking_rule,definition=excluded.definition,active=true;
insert into public.abilities(id,game_version_id,banner_id,name,timing,mechanics,stacking_rule,definition,active) select 'moonrush',id,'wild_courts','Moonrush','after_attack','After this unit completes its attack in rounds 3, 6, 9, and so on, it repeats the same attack against a newly selected legal target at 70% power, rounded down, minimum 1.','Additional copies do not create more repeats.','{"values":{"everyNthRound":3,"repeatPowerPercent":70},"interactions":["The repeat performs a fresh accuracy roll.","On-attack effects can trigger on both attacks unless limited per round.","A defeated original target is retargeted normally."]}'::jsonb,true from public.game_versions where version='three-packs-1.0.0' on conflict(id) do update set game_version_id=excluded.game_version_id,banner_id=excluded.banner_id,name=excluded.name,timing=excluded.timing,mechanics=excluded.mechanics,stacking_rule=excluded.stacking_rule,definition=excluded.definition,active=true;
insert into public.abilities(id,game_version_id,banner_id,name,timing,mechanics,stacking_rule,definition,active) select 'trailblazer',id,'wild_courts','Trailblazer','after_position_change','When this unit moves toward position 1 because an ally was defeated, gain +2 speed until round end and clear Pin.','Refreshes duration; does not add more speed.','{"values":{"speedBonus":2},"interactions":["Voluntary swaps do not trigger it.","The speed change affects any remaining action this round.","No Retreat prevents the movement and therefore the trigger."]}'::jsonb,true from public.game_versions where version='three-packs-1.0.0' on conflict(id) do update set game_version_id=excluded.game_version_id,banner_id=excluded.banner_id,name=excluded.name,timing=excluded.timing,mechanics=excluded.mechanics,stacking_rule=excluded.stacking_rule,definition=excluded.definition,active=true;
insert into public.abilities(id,game_version_id,banner_id,name,timing,mechanics,stacking_rule,definition,active) select 'primal_mend',id,'wild_courts','Primal Mend','after_kill','The first time this unit defeats an enemy each round, restore 2 health to the wounded allied Wild Courts unit with the lowest health percentage; ties favor the frontmost.','Each bearer can trigger once per round.','{"values":{"healing":2,"usesPerRound":1},"interactions":["Cannot target the bearer if another eligible ally has a lower percentage.","Overhealing is lost.","Healing modifiers apply after target selection."]}'::jsonb,true from public.game_versions where version='three-packs-1.0.0' on conflict(id) do update set game_version_id=excluded.game_version_id,banner_id=excluded.banner_id,name=excluded.name,timing=excluded.timing,mechanics=excluded.mechanics,stacking_rule=excluded.stacking_rule,definition=excluded.definition,active=true;
insert into public.abilities(id,game_version_id,banner_id,name,timing,mechanics,stacking_rule,definition,active) select 'mislead',id,'veil_covenant','Mislead','before_target_lock','Once per round, when an enemy directly targets another allied back-rank unit, redirect that action to this unit if this unit is a legal target.','Nearest rearward eligible bearer resolves first.','{"values":{"usesPerRound":1,"backRankPositions":[3,4,5,6]},"interactions":["Does not redirect attacks already aimed at position 1.","Area and random-target actions cannot be redirected.","The attacker does not reroll accuracy after redirection."]}'::jsonb,true from public.game_versions where version='three-packs-1.0.0' on conflict(id) do update set game_version_id=excluded.game_version_id,banner_id=excluded.banner_id,name=excluded.name,timing=excluded.timing,mechanics=excluded.mechanics,stacking_rule=excluded.stacking_rule,definition=excluded.definition,active=true;
insert into public.abilities(id,game_version_id,banner_id,name,timing,mechanics,stacking_rule,definition,active) select 'fate_knot',id,'veil_covenant','Fate Knot','battle_start','Link to the adjacent ally with the lowest printed mana; ties favor the frontward ally. Whenever either linked unit takes 2 or more post-mitigation damage, move 1 of that damage to the other as direct damage.','A unit may belong to only one knot; earlier formation position wins conflicts.','{"values":{"shiftedDamage":1,"minimumTriggerDamage":2},"interactions":["Shifted damage cannot trigger another Fate Knot.","The link ends when either unit is defeated.","Oathkeeper resolves before the knot."]}'::jsonb,true from public.game_versions where version='three-packs-1.0.0' on conflict(id) do update set game_version_id=excluded.game_version_id,banner_id=excluded.banner_id,name=excluded.name,timing=excluded.timing,mechanics=excluded.mechanics,stacking_rule=excluded.stacking_rule,definition=excluded.definition,active=true;
insert into public.abilities(id,game_version_id,banner_id,name,timing,mechanics,stacking_rule,definition,active) select 'hexweave',id,'veil_covenant','Hexweave','after_hit','The first hit each round applies the next hex in a repeating sequence: -1 speed; then -1 attack power; then healing locked. Each hex lasts through the next round.','Different hexes coexist; the same hex refreshes but does not stack.','{"values":{"speedPenalty":1,"attackPenalty":1,"durationRounds":1},"interactions":["The sequence is stored per bearer.","Attack power reduces all three attack channels, minimum 0.","Cleanse removes the active hex but does not reset the sequence."]}'::jsonb,true from public.game_versions where version='three-packs-1.0.0' on conflict(id) do update set game_version_id=excluded.game_version_id,banner_id=excluded.banner_id,name=excluded.name,timing=excluded.timing,mechanics=excluded.mechanics,stacking_rule=excluded.stacking_rule,definition=excluded.definition,active=true;
insert into public.abilities(id,game_version_id,banner_id,name,timing,mechanics,stacking_rule,definition,active) select 'echo_sigil',id,'veil_covenant','Echo Sigil','after_support_action','Once per round, repeat this unit’s first numeric support action at 50% value, rounded down, minimum 1, on the same target if still legal or the next legal target by the original selector.','Additional copies add no repeats.','{"values":{"repeatPercent":50,"usesPerRound":1},"interactions":["Cannot repeat resurrection, ability grants, displacement, or another Echo Sigil.","The repeat is a new event for triggers.","Echoing Hall modifies the original action before this repeat is calculated."]}'::jsonb,true from public.game_versions where version='three-packs-1.0.0' on conflict(id) do update set game_version_id=excluded.game_version_id,banner_id=excluded.banner_id,name=excluded.name,timing=excluded.timing,mechanics=excluded.mechanics,stacking_rule=excluded.stacking_rule,definition=excluded.definition,active=true;
insert into public.abilities(id,game_version_id,banner_id,name,timing,mechanics,stacking_rule,definition,active) select 'vanish',id,'veil_covenant','Vanish','after_damage','The first time each battle this unit loses its last armor, it becomes untargetable by direct attacks from positions 3–6 until after its next action.','Additional copies add no uses.','{"values":{"usesPerBattle":1,"blockedAttackerPositions":[3,4,5,6]},"interactions":["Does not cancel the action that broke the armor.","Area, indirect, and front-rank attacks remain legal.","If stunned, Vanish lasts until after the skipped action resolves."]}'::jsonb,true from public.game_versions where version='three-packs-1.0.0' on conflict(id) do update set game_version_id=excluded.game_version_id,banner_id=excluded.banner_id,name=excluded.name,timing=excluded.timing,mechanics=excluded.mechanics,stacking_rule=excluded.stacking_rule,definition=excluded.definition,active=true;
insert into public.abilities(id,game_version_id,banner_id,name,timing,mechanics,stacking_rule,definition,active) select 'mirrorcraft',id,'veil_covenant','Mirrorcraft','round_start','Set this unit’s speed to the highest current enemy speed until round end, but never below its printed speed.','One recalculation; copies do not stack.','{"values":{"floor":"printedSpeed"},"interactions":["Reads enemy speed after round-start penalties but before initiative ordering.","Later speed changes still apply to the copied value.","If there are no enemies, no change occurs."]}'::jsonb,true from public.game_versions where version='three-packs-1.0.0' on conflict(id) do update set game_version_id=excluded.game_version_id,banner_id=excluded.banner_id,name=excluded.name,timing=excluded.timing,mechanics=excluded.mechanics,stacking_rule=excluded.stacking_rule,definition=excluded.definition,active=true;
insert into public.abilities(id,game_version_id,banner_id,name,timing,mechanics,stacking_rule,definition,active) select 'soul_tithe',id,'hollow_legions','Soul Tithe','after_unit_defeated','Gain 1 soul whenever any other unit is defeated. At 3 souls, automatically spend 3 to heal 3 health and remove the oldest removable negative status from this unit.','Each bearer tracks souls independently.','{"values":{"soulsRequired":3,"healing":3,"maximumSouls":3},"interactions":["Battle-start defeats grant souls.","Cannot trigger after the bearer is defeated.","If at full health with no removable status, souls remain stored."]}'::jsonb,true from public.game_versions where version='three-packs-1.0.0' on conflict(id) do update set game_version_id=excluded.game_version_id,banner_id=excluded.banner_id,name=excluded.name,timing=excluded.timing,mechanics=excluded.mechanics,stacking_rule=excluded.stacking_rule,definition=excluded.definition,active=true;
insert into public.abilities(id,game_version_id,banner_id,name,timing,mechanics,stacking_rule,definition,active) select 'grave_recall',id,'hollow_legions','Grave Recall','after_self_defeated','Once per battle, return in the same position after the current action with 2 health, 0 armor, -1 attack power, and support actions disabled.','Additional copies add no revivals.','{"values":{"returnedHealth":2,"attackPenalty":1,"usesPerBattle":1},"interactions":["The return is the same unit identity and keeps once-per-battle usage.","Cannot trigger if its position was filled by a summon.","Victory is checked after pending returns resolve."]}'::jsonb,true from public.game_versions where version='three-packs-1.0.0' on conflict(id) do update set game_version_id=excluded.game_version_id,banner_id=excluded.banner_id,name=excluded.name,timing=excluded.timing,mechanics=excluded.mechanics,stacking_rule=excluded.stacking_rule,definition=excluded.definition,active=true;
insert into public.abilities(id,game_version_id,banner_id,name,timing,mechanics,stacking_rule,definition,active) select 'death_debt',id,'hollow_legions','Death Debt','after_damage','The first enemy each round to deal positive direct damage to this unit gains a debt. At round end, that enemy takes 2 direct damage and the debt is removed.','One debt from each bearer may coexist on the same enemy.','{"values":{"debtDamage":2,"debtsPlacedPerRound":1},"interactions":["The debt persists if the bearer is defeated.","Direct damage ignores armor and Brace.","A defeated debtor is removed before the debt resolves."]}'::jsonb,true from public.game_versions where version='three-packs-1.0.0' on conflict(id) do update set game_version_id=excluded.game_version_id,banner_id=excluded.banner_id,name=excluded.name,timing=excluded.timing,mechanics=excluded.mechanics,stacking_rule=excluded.stacking_rule,definition=excluded.definition,active=true;
insert into public.abilities(id,game_version_id,banner_id,name,timing,mechanics,stacking_rule,definition,active) select 'bone_harvest',id,'hollow_legions','Bone Harvest','after_unit_defeated','Whenever another unit is defeated, gain 1 armor, up to 3 gained armor during each life.','Each copy raises the per-life cap by 1, not the gain.','{"values":{"armorPerDefeat":1,"maximumPerLife":3},"interactions":["A Grave Recall return begins a new life and resets the cap.","Cannot exceed printed maximum armor plus 3.","Simultaneous defeats resolve front to back, ally before enemy."]}'::jsonb,true from public.game_versions where version='three-packs-1.0.0' on conflict(id) do update set game_version_id=excluded.game_version_id,banner_id=excluded.banner_id,name=excluded.name,timing=excluded.timing,mechanics=excluded.mechanics,stacking_rule=excluded.stacking_rule,definition=excluded.definition,active=true;
insert into public.abilities(id,game_version_id,banner_id,name,timing,mechanics,stacking_rule,definition,active) select 'doom_count',id,'hollow_legions','Doom Count','after_hit','The first hit against each target places a counter at 3. At each round end it decreases by 1; at 0 the target takes 3 direct damage and the counter ends.','One count per source; a new hit refreshes it to 3.','{"values":{"startingCount":3,"expiryDamage":3},"interactions":["Cleanse removes the counter.","The source need not remain alive.","The count ticks after Death Debt and before fatigue."]}'::jsonb,true from public.game_versions where version='three-packs-1.0.0' on conflict(id) do update set game_version_id=excluded.game_version_id,banner_id=excluded.banner_id,name=excluded.name,timing=excluded.timing,mechanics=excluded.mechanics,stacking_rule=excluded.stacking_rule,definition=excluded.definition,active=true;
insert into public.abilities(id,game_version_id,banner_id,name,timing,mechanics,stacking_rule,definition,active) select 'pale_exchange',id,'hollow_legions','Pale Exchange','before_support_action','Once per round, this unit may pay 1 health to increase the numeric value of its next heal, armor restore, or debuff by 2. It cannot pay if at 1 health.','Additional copies add no uses.','{"values":{"healthCost":1,"potencyBonus":2,"usesPerRound":1},"interactions":["The health cost is direct and cannot be prevented.","If the action is canceled, the cost is refunded.","Echo Sigil repeats the increased final value at half strength."]}'::jsonb,true from public.game_versions where version='three-packs-1.0.0' on conflict(id) do update set game_version_id=excluded.game_version_id,banner_id=excluded.banner_id,name=excluded.name,timing=excluded.timing,mechanics=excluded.mechanics,stacking_rule=excluded.stacking_rule,definition=excluded.definition,active=true;
insert into public.abilities(id,game_version_id,banner_id,name,timing,mechanics,stacking_rule,definition,active) select 'windread',id,'skybound_houses','Windread','continuous','While in position 4, 5, or 6, gain +1 speed and +10 accuracy.','Additional copies do not stack.','{"values":{"speedBonus":1,"accuracyBonus":10,"eligiblePositions":[4,5,6]},"interactions":["Recalculates immediately after movement.","Accuracy is on a 0–100 scale.","Open Flanks adds after Windread."]}'::jsonb,true from public.game_versions where version='three-packs-1.0.0' on conflict(id) do update set game_version_id=excluded.game_version_id,banner_id=excluded.banner_id,name=excluded.name,timing=excluded.timing,mechanics=excluded.mechanics,stacking_rule=excluded.stacking_rule,definition=excluded.definition,active=true;
insert into public.abilities(id,game_version_id,banner_id,name,timing,mechanics,stacking_rule,definition,active) select 'dive_pass',id,'skybound_houses','Dive Pass','after_attack','After this unit hits with a Steel attack from position 3–6, swap it with the allied unit immediately ahead, unless either unit is pinned or anchored.','At most one swap per attack.','{"values":{"eligiblePositions":[3,4,5,6],"moveDistance":1},"interactions":["The swap occurs after all hit triggers.","No Retreat disables the swap.","Trailblazer does not trigger because the movement was not caused by a defeat."]}'::jsonb,true from public.game_versions where version='three-packs-1.0.0' on conflict(id) do update set game_version_id=excluded.game_version_id,banner_id=excluded.banner_id,name=excluded.name,timing=excluded.timing,mechanics=excluded.mechanics,stacking_rule=excluded.stacking_rule,definition=excluded.definition,active=true;
insert into public.abilities(id,game_version_id,banner_id,name,timing,mechanics,stacking_rule,definition,active) select 'spotter',id,'skybound_houses','Spotter','after_hit','The first enemy this unit hits each round is spotted until round end. Allied Shot attacks against it ignore 1 armor and gain +5 accuracy.','Multiple Spotter marks refresh; armor ignore is capped at 2.','{"values":{"ignoredArmor":1,"accuracyBonus":5,"usesPerRound":1},"interactions":["Ignored armor is not removed; that portion of damage reaches health.","A miss does not spot.","Packmark and Spotter bonuses may coexist."]}'::jsonb,true from public.game_versions where version='three-packs-1.0.0' on conflict(id) do update set game_version_id=excluded.game_version_id,banner_id=excluded.banner_id,name=excluded.name,timing=excluded.timing,mechanics=excluded.mechanics,stacking_rule=excluded.stacking_rule,definition=excluded.definition,active=true;
insert into public.abilities(id,game_version_id,banner_id,name,timing,mechanics,stacking_rule,definition,active) select 'volley_line',id,'skybound_houses','Volley Line','continuous','If this unit has an adjacent living ally with a printed Shot value above 0, both units gain +1 Shot power.','A unit can receive at most +1 from Volley Line, regardless of neighbors.','{"values":{"shotBonus":1},"interactions":["Broken Formation suppresses the bonus.","The bonus ends immediately when adjacency changes.","A unit whose Shot value was granted rather than printed does not qualify."]}'::jsonb,true from public.game_versions where version='three-packs-1.0.0' on conflict(id) do update set game_version_id=excluded.game_version_id,banner_id=excluded.banner_id,name=excluded.name,timing=excluded.timing,mechanics=excluded.mechanics,stacking_rule=excluded.stacking_rule,definition=excluded.definition,active=true;
insert into public.abilities(id,game_version_id,banner_id,name,timing,mechanics,stacking_rule,definition,active) select 'crosswind',id,'skybound_houses','Crosswind','after_action','After this unit acts, the next living enemy in the current initiative queue receives -2 speed for the next round.','Penalties from different bearers stack to a maximum of -4.','{"values":{"speedPenalty":2,"durationRounds":1},"interactions":["Does not change the current queue.","If no enemy remains in the queue, target the fastest living enemy.","Mirrorcraft reads the penalty at the next round start."]}'::jsonb,true from public.game_versions where version='three-packs-1.0.0' on conflict(id) do update set game_version_id=excluded.game_version_id,banner_id=excluded.banner_id,name=excluded.name,timing=excluded.timing,mechanics=excluded.mechanics,stacking_rule=excluded.stacking_rule,definition=excluded.definition,active=true;
insert into public.abilities(id,game_version_id,banner_id,name,timing,mechanics,stacking_rule,definition,active) select 'skyhook',id,'skybound_houses','Skyhook','after_hit','When this unit’s Shot attack breaks a target’s armor, pull that target one position toward the front if the destination is legal.','One pull per attack.','{"values":{"moveDistance":1},"interactions":["Anchor and No Retreat prevent the pull.","A target already in position 1 does not move.","Formation closes normally after the displaced unit changes position."]}'::jsonb,true from public.game_versions where version='three-packs-1.0.0' on conflict(id) do update set game_version_id=excluded.game_version_id,banner_id=excluded.banner_id,name=excluded.name,timing=excluded.timing,mechanics=excluded.mechanics,stacking_rule=excluded.stacking_rule,definition=excluded.definition,active=true;
insert into public.abilities(id,game_version_id,banner_id,name,timing,mechanics,stacking_rule,definition,active) select 'ancient_scale',id,'wyrm_clans','Ancient Scale','damage_mitigation','The first time each round this unit would take 4 or more damage from one event, reduce it by 2 and gain 1 rage.','Copies do not add reductions; each extra copy raises maximum rage by 1.','{"values":{"triggerDamage":4,"reduction":2,"maximumRage":3},"interactions":["Rage is a resource used by other Wyrm effects and persists between rounds.","Checked after armor but before direct damage conversion.","Damage reduced below 1 still counts as damage."]}'::jsonb,true from public.game_versions where version='three-packs-1.0.0' on conflict(id) do update set game_version_id=excluded.game_version_id,banner_id=excluded.banner_id,name=excluded.name,timing=excluded.timing,mechanics=excluded.mechanics,stacking_rule=excluded.stacking_rule,definition=excluded.definition,active=true;
insert into public.abilities(id,game_version_id,banner_id,name,timing,mechanics,stacking_rule,definition,active) select 'hoardfire',id,'wyrm_clans','Hoardfire','battle_start','Gain +1 Spell power for every 3 unspent team mana left after drafting, to a maximum of +2.','Each bearer calculates independently; copies on one unit do not stack.','{"values":{"manaPerBonus":3,"maximumBonus":2},"interactions":["Blood Price changes card costs before unspent mana is calculated.","The bonus is fixed for the battle.","A unit with printed Spell 0 may gain Spell power but still needs legal Spell targeting."]}'::jsonb,true from public.game_versions where version='three-packs-1.0.0' on conflict(id) do update set game_version_id=excluded.game_version_id,banner_id=excluded.banner_id,name=excluded.name,timing=excluded.timing,mechanics=excluded.mechanics,stacking_rule=excluded.stacking_rule,definition=excluded.definition,active=true;
insert into public.abilities(id,game_version_id,banner_id,name,timing,mechanics,stacking_rule,definition,active) select 'devour_oath',id,'wyrm_clans','Devour Oath','after_kill','When this unit defeats an enemy, steal the oldest removable positive numeric status from that enemy at its remaining value and duration.','Additional copies steal one extra status, maximum 2.','{"values":{"statusesStolenPerKill":1},"interactions":["Printed stats, summoner effects, and abilities cannot be stolen.","If no legal status exists, nothing happens.","The defeated unit’s after-defeat effects resolve after the theft."]}'::jsonb,true from public.game_versions where version='three-packs-1.0.0' on conflict(id) do update set game_version_id=excluded.game_version_id,banner_id=excluded.banner_id,name=excluded.name,timing=excluded.timing,mechanics=excluded.mechanics,stacking_rule=excluded.stacking_rule,definition=excluded.definition,active=true;
insert into public.abilities(id,game_version_id,banner_id,name,timing,mechanics,stacking_rule,definition,active) select 'runebreath',id,'wyrm_clans','Runebreath','before_attack','Cycle this unit’s attack channel for each attack: Steel, then Spell, then Shot, repeating. Power remains equal to its highest printed attack value.','Additional copies do not alter the sequence.','{"values":{"sequence":["steel","spell","shot"]},"interactions":["The cycle advances even on a miss.","Target legality is recalculated for the chosen channel.","Moonrush repeats use the next channel in sequence."]}'::jsonb,true from public.game_versions where version='three-packs-1.0.0' on conflict(id) do update set game_version_id=excluded.game_version_id,banner_id=excluded.banner_id,name=excluded.name,timing=excluded.timing,mechanics=excluded.mechanics,stacking_rule=excluded.stacking_rule,definition=excluded.definition,active=true;
insert into public.abilities(id,game_version_id,banner_id,name,timing,mechanics,stacking_rule,definition,active) select 'colossus_wake',id,'wyrm_clans','Colossus Wake','continuous','Adjacent allies gain +1 maximum health and cannot be moved by enemy effects.','Health bonuses from two adjacent bearers stack to +2; movement immunity does not stack.','{"values":{"maximumHealthBonus":1},"interactions":["Broken Formation suppresses both effects.","Current health rises and falls with maximum health, but never below 1 when the aura ends.","Allied voluntary movement remains legal."]}'::jsonb,true from public.game_versions where version='three-packs-1.0.0' on conflict(id) do update set game_version_id=excluded.game_version_id,banner_id=excluded.banner_id,name=excluded.name,timing=excluded.timing,mechanics=excluded.mechanics,stacking_rule=excluded.stacking_rule,definition=excluded.definition,active=true;
insert into public.abilities(id,game_version_id,banner_id,name,timing,mechanics,stacking_rule,definition,active) select 'bloodline_roar',id,'wyrm_clans','Bloodline Roar','after_health_change','The first time each allied unit falls to half maximum health or lower, that unit gains +1 attack power for the rest of its current life.','One roar bonus per ally; multiple bearers do not add more.','{"values":{"attackBonus":1,"thresholdPercent":50},"interactions":["A unit already below half at battle start triggers after the first health change.","Grave Recall creates a new life and can trigger again.","Attack power affects Steel, Shot, and Spell values above 0."]}'::jsonb,true from public.game_versions where version='three-packs-1.0.0' on conflict(id) do update set game_version_id=excluded.game_version_id,banner_id=excluded.banner_id,name=excluded.name,timing=excluded.timing,mechanics=excluded.mechanics,stacking_rule=excluded.stacking_rule,definition=excluded.definition,active=true;
