insert into public.rulesets(id,game_version_id,name,category,phase,description,definition,incompatible_with,selection_weight,active) select 'fickle_fortune',id,'Fickle Fortune','randomness','round_start','At each round start, seeded battle RNG selects one living unit per team. It gains +1 speed for that round. The seed and eligible ordering make replays deterministic.','{"speedBonus":1,"selectionsPerTeam":1,"rng":"seeded"}'::jsonb,array[]::text[],100,true from public.game_versions where version='three-packs-1.0.0' on conflict(id) do update set game_version_id=excluded.game_version_id,name=excluded.name,category=excluded.category,phase=excluded.phase,description=excluded.description,definition=excluded.definition,incompatible_with=excluded.incompatible_with,selection_weight=excluded.selection_weight,active=true;
